insert into gov_repo.mandates(mandate_code,regulation,section_ref,title,requirement_text,requirement_type,effective_date,applicability,mapped_controls) values
('DORA-ART-17','DORA (EU 2022/2554)','Art. 17','ICT-Related Incident Management Process','Financial entities shall define, establish and implement an ICT-related incident management process.','mandatory','2025-01-17','{"sectors":["banking","insurance","investment_firm","payment_institution"]}',array['CG-AG-008','CG-AG-011']),
('DORA-ART-18','DORA (EU 2022/2554)','Art. 18','Classification of ICT-Related Incidents','Financial entities shall classify ICT-related incidents using harmonised criteria.','mandatory','2025-01-17','{"sectors":["banking","insurance","investment_firm","payment_institution"]}',array['CG-AG-010']),
('DORA-ART-19','DORA (EU 2022/2554)','Art. 19','Reporting of Major ICT-Related Incidents','Financial entities shall report major ICT incidents to the competent authority using prescribed timelines.','mandatory','2025-01-17','{"sectors":["banking","insurance","investment_firm","payment_institution"]}',array['CG-AG-008']),
('DORA-ART-20','DORA (EU 2022/2554)','Art. 20','Harmonisation of Reporting Content and Timelines','Financial entities must use approved technical standards and templates for DORA reports.','mandatory','2025-01-17','{"sectors":["banking","insurance","investment_firm","payment_institution"]}',array['CG-AG-008']),
('DORA-ART-21','DORA (EU 2022/2554)','Art. 21','Voluntary Notification of Significant Cyber Threats','Financial entities may voluntarily notify significant cyber threats.','recommended','2025-01-17','{"sectors":["banking","insurance","investment_firm","payment_institution"]}',array['CG-AG-010']),
('NIST-RESPOND-1-1','NIST AI RMF 1.0','RESPOND 1.1','Incident Response Policies and Procedures','Policies, procedures and practices are in place to address AI risks during deployment and use.','recommended','2023-01-26','{"sectors":["all"]}',array['CG-AG-007','CG-AG-008','CG-AG-012']),
('NIST-RESPOND-2-1','NIST AI RMF 1.0','RESPOND 2.1','Incident Containment and Recovery','Responses to AI risks and incidents are communicated and lessons learned reflected in governance.','recommended','2023-01-26','{"sectors":["all"]}',array['CG-AG-008','CG-AG-010']),
('ISO42001-8-2','ISO/IEC 42001:2023','Clause 8.2','AI System Incident Management','The organisation shall establish and maintain an AI incident management process.','mandatory','2023-12-18','{"sectors":["all"]}',array['CG-AG-008','CG-AG-010','CG-AG-012']),
('ISO27001-A-5-24','ISO/IEC 27001:2022','A.5.24','Information Security Incident Management Planning and Preparation','The organisation shall plan and prepare for managing information security incidents.','mandatory','2022-10-25','{"sectors":["all"]}',array['CG-AG-008']),
('ISO27001-A-5-26','ISO/IEC 27001:2022','A.5.26','Response to Information Security Incidents','Incidents shall be responded to in accordance with documented procedures.','mandatory','2022-10-25','{"sectors":["all"]}',array['CG-AG-008']) on conflict(mandate_code) do nothing;
