create or replace function gov_repo.ict_incident_impact_summary(p_incident_id uuid)
returns table(incident_id uuid,incident_code varchar,title varchar,severity gov_repo.incident_severity,total_downtime_mins integer,rto_breach boolean,rpo_breach boolean,services_affected bigint,critical_services_down bigint,ai_systems_affected bigint,agents_affected bigint,providers_affected bigint,clients_affected_total bigint,financial_impact_eur numeric,pii_data_exposed boolean,notifications_sent bigint,notifications_overdue bigint,recovery_progress_pct integer,has_lessons_learned boolean)
language sql security definer as $$ select i.incident_id,i.incident_code,i.title,i.severity,i.downtime_minutes,i.rto_breach,i.rpo_breach,(select count(*) from gov_repo.ict_incident_affected_services s where s.incident_id=i.incident_id),(select count(*) from gov_repo.ict_incident_affected_services s where s.incident_id=i.incident_id and s.ict_function_type in ('critical','important') and s.service_impact='full_outage'),(select count(distinct s.ai_system_id) from gov_repo.ict_incident_affected_services s where s.incident_id=i.incident_id and s.ai_system_id is not null),cardinality(i.impacted_agent_ids),cardinality(i.impacted_provider_ids),(select coalesce(sum(s.clients_affected),0) from gov_repo.ict_incident_affected_services s where s.incident_id=i.incident_id),coalesce(i.financial_impact_eur,0),i.pii_data_exposed,(select count(*) from gov_repo.ict_incident_notifications n where n.incident_id=i.incident_id),(select count(*) from gov_repo.ict_incident_notifications n where n.incident_id=i.incident_id and n.is_breached=true),case i.recovery_status when 'not_started' then 0 when 'containment_active' then 15 when 'eradication_active' then 35 when 'recovery_active' then 55 when 'restored_partial' then 70 when 'restored_full' then 85 when 'monitoring_period' then 90 when 'lessons_learned_pending' then 95 when 'closed' then 100 else 0 end,(i.lessons_learned is not null) from gov_repo.ict_incidents i where i.incident_id=p_incident_id; $$;
grant execute on function gov_repo.compute_dora_reporting_deadlines to service_role;grant execute on function gov_repo.sync_ai_system_incident_count to service_role;grant execute on function gov_repo.ict_incident_classify_major to service_role,authenticated;grant execute on function gov_repo.ict_dora_sla_status to service_role,authenticated;grant execute on function gov_repo.ict_incident_impact_summary to service_role,authenticated;;
